<template>
  <div class="page">
    <div v-if="loading" class="loading-container">
      <div class="spinner-green" />
      <p class="loading-text">Loading orders...</p>
    </div>

    <div
      v-else
      class="scroll-wrap"
      @touchstart.passive="onTouchStart"
      @touchend="onTouchEnd"
    >
      <div
        ref="scrollEl"
        class="scroll-view"
        :class="{ 'empty-scroll': deliveries.length === 0 }"
        @scroll.passive="onScrollPull"
      >
        <template v-if="deliveries.length === 0">
          <div class="empty-container">
            <p class="empty-text">No new orders available</p>
            <p class="empty-subtext">
              Pull down to refresh and check for new orders
            </p>
          </div>
        </template>
        <template v-else>
          <div class="pager-bar">
            <button
              type="button"
              class="pager-button"
              :class="{ 'pager-button-disabled': !canGoPrev }"
              :disabled="!canGoPrev"
              @click="prev"
            >
              <span class="pager-inner">
                <span
                  class="pager-glyph"
                  :class="{ 'pager-glyph-disabled': !canGoPrev }"
                  >◀</span
                >
                <span
                  class="pager-text"
                  :class="{ 'pager-text-disabled': !canGoPrev }"
                  >Previous</span
                >
              </span>
            </button>
            <span class="pager-counter">{{ safeIndex + 1 }} of {{ total }}</span>
            <button
              type="button"
              class="pager-button"
              :class="{ 'pager-button-disabled': !canGoNext }"
              :disabled="!canGoNext"
              @click="next"
            >
              <span class="pager-inner">
                <span
                  class="pager-text"
                  :class="{ 'pager-text-disabled': !canGoNext }"
                  >Next</span
                >
                <span
                  class="pager-glyph"
                  :class="{ 'pager-glyph-disabled': !canGoNext }"
                  >▶</span
                >
              </span>
            </button>
          </div>
          <div v-if="currentDelivery" class="delivery-card">
            <div class="section-card">
              <h3 class="section-heading">Summary</h3>
              <div class="detail-row">
                <span class="detail-label">Earnings</span>
                <span class="detail-value detail-value-teal">{{
                  formatOrderTotal(currentDelivery)
                }}</span>
              </div>
            </div>

            <div v-if="currentDelivery.restaurant" class="section-card">
              <h3 class="section-heading">Pickup</h3>
              <p class="body-text-strong">{{ currentDelivery.restaurant.name }}</p>
              <p v-if="currentDelivery.restaurant.address" class="body-text-muted">
                {{ currentDelivery.restaurant.address
                }}{{
                  currentDelivery.restaurant.postcode
                    ? `, ${currentDelivery.restaurant.postcode}`
                    : ''
                }}
              </p>
            </div>

            <div class="section-card">
              <h3 class="section-heading">Drop-off</h3>
              <p class="body-text-muted">
                {{ currentDelivery.address
                }}{{
                  currentDelivery.postcode
                    ? `, ${currentDelivery.postcode}`
                    : ''
                }}
              </p>
              <div class="eta-row">
                <span class="detail-label">Distance &amp; ETA</span>
                <span v-if="!dropoffForCurrent || dropoffForCurrent.loading" class="eta-loading"
                  >…</span
                >
                <span
                  v-else-if="dropoffForCurrent.error"
                  class="eta-error"
                  >{{ dropoffForCurrent.error }}</span
                >
                <span v-else class="eta-value">{{ etaLine(dropoffForCurrent) }}</span>
              </div>
            </div>

            <div class="button-row">
              <button
                type="button"
                class="reject-button"
                @click="handleDecline(currentDelivery.id)"
              >
                <span class="compact-inner">
                  <span class="reject-glyph">✕</span>
                  <span>Reject</span>
                </span>
              </button>
              <button
                type="button"
                class="accept-button"
                @click="handleAccept(currentDelivery.id)"
              >
                <span class="compact-inner">
                  <span class="accept-glyph">✓</span>
                  <span>Accept</span>
                </span>
              </button>
            </div>
          </div>
        </template>
      </div>
      <div v-if="refreshing" class="refresh-indicator">Refreshing…</div>
    </div>
  </div>
</template>

<script>
import { mapState } from 'vuex';
import ApiService from '../services/api';
import LocationService from '../services/location';
import { formatOrderTotal } from '../utils/orderFormat';

export default {
  name: 'PendingOrdersView',
  data() {
    return {
      deliveries: [],
      loading: true,
      refreshing: false,
      deviceLocation: null,
      locationError: null,
      distances: {},
      currentIndex: 0,
      pullStartY: null,
      touchStartY: null,
    };
  },
  computed: {
    ...mapState('auth', ['user']),
    total() {
      return this.deliveries.length;
    },
    safeIndex() {
      const t = this.total;
      if (t <= 0) return 0;
      return Math.min(this.currentIndex, t - 1);
    },
    currentDelivery() {
      if (this.total <= 0) return undefined;
      return this.deliveries[this.safeIndex];
    },
    canGoPrev() {
      return this.total > 0 && this.safeIndex > 0;
    },
    canGoNext() {
      return this.total > 0 && this.safeIndex < this.total - 1;
    },
    dropoffForCurrent() {
      const d = this.currentDelivery;
      if (!d || !this.distances[d.id]) return null;
      return this.distances[d.id].dropoff;
    },
  },
  mounted() {
    this.fetchPendingOrders();
    this.getDeviceLocation();
    this.locationInterval = setInterval(() => {
      this.getDeviceLocation();
    }, 30000);
  },
  beforeDestroy() {
    if (this.locationInterval) {
      clearInterval(this.locationInterval);
    }
  },
  watch: {
    deliveries: {
      handler(val) {
        if (val.length === 0) {
          this.currentIndex = 0;
        } else {
          this.currentIndex = Math.min(this.currentIndex, val.length - 1);
        }
        this.$nextTick(() => this.maybeCalculateDistances());
      },
      deep: true,
    },
    deviceLocation() {
      this.maybeCalculateDistances();
    },
  },
  methods: {
    formatOrderTotal,
    onTouchStart(e) {
      if (e.touches && e.touches[0]) {
        this.touchStartY = e.touches[0].clientY;
      }
    },
    onTouchEnd(e) {
      if (this.touchStartY == null || !e.changedTouches || !e.changedTouches[0]) {
        return;
      }
      const dy = e.changedTouches[0].clientY - this.touchStartY;
      this.touchStartY = null;
      if (dy > 80 && this.$refs.scrollEl && this.$refs.scrollEl.scrollTop <= 0) {
        this.onRefresh();
      }
    },
    onScrollPull() {
      /* pull handled via touch for simplicity */
    },
    async fetchPendingOrders() {
      try {
        const response = await ApiService.get('/driver/deliveries/new');

        let deliveriesList = [];

        if (response.success !== false) {
          if (response.deliveries) {
            deliveriesList = response.deliveries;
          } else if (response.data && response.data.deliveries) {
            deliveriesList = response.data.deliveries;
          } else if (Array.isArray(response.data)) {
            deliveriesList = response.data;
          } else if (Array.isArray(response)) {
            deliveriesList = response;
          }

          const pendingOrders = deliveriesList.filter(
            (delivery) => delivery.status === 'pending'
          );
          this.deliveries = pendingOrders;
        } else {
          window.alert(response.message || 'Failed to load orders');
        }
      } catch (error) {
        console.error('Error fetching orders:', error);
        window.alert(error.message || 'Failed to load orders');
      } finally {
        this.loading = false;
        this.refreshing = false;
      }
    },
    async getDeviceLocation() {
      try {
        const location = await LocationService.getCurrentLocation();

        if (location) {
          this.deviceLocation = {
            latitude: location.latitude,
            longitude: location.longitude,
          };
          this.locationError = null;
        } else if (this.user && this.user.latitude && this.user.longitude) {
          this.deviceLocation = {
            latitude: this.user.latitude,
            longitude: this.user.longitude,
          };
          this.locationError = null;
        } else {
          this.locationError =
            'Unable to get your location. Please enable location services.';
        }
      } catch (error) {
        if (this.user && this.user.latitude && this.user.longitude) {
          this.deviceLocation = {
            latitude: this.user.latitude,
            longitude: this.user.longitude,
          };
          this.locationError = null;
        } else {
          this.locationError =
            'Unable to get your location. Please enable location services.';
        }
      }
    },
    maybeCalculateDistances() {
      if (this.deliveries.length > 0 && this.deviceLocation) {
        this.calculateDistances();
      }
    },
    async calculateDistances() {
      if (!this.deviceLocation) return;

      const loc = this.deviceLocation;
      const init = {};
      this.deliveries.forEach((delivery) => {
        init[delivery.id] = {
          pickup: { distance: '', duration: '', loading: true },
          dropoff: { distance: '', duration: '', loading: true },
        };
      });
      this.distances = { ...init };

      for (const delivery of this.deliveries) {
        if (delivery.restaurant) {
          await this.calculateDistanceTime(
            delivery.id,
            'pickup',
            loc.latitude,
            loc.longitude,
            delivery.restaurant.latitude || null,
            delivery.restaurant.longitude || null,
            delivery.restaurant.address || null
          );
        }
        await this.calculateDistanceTime(
          delivery.id,
          'dropoff',
          loc.latitude,
          loc.longitude,
          delivery.latitude || null,
          delivery.longitude || null,
          delivery.address || null
        );
      }
    },
    async calculateDistanceTime(
      deliveryId,
      type,
      originLat,
      originLng,
      destLat,
      destLng,
      destAddress
    ) {
      try {
        const requestBody = {
          origin_lat: originLat,
          origin_lng: originLng,
        };

        if (destLat && destLng) {
          requestBody.destination_lat = destLat;
          requestBody.destination_lng = destLng;
        } else if (destAddress) {
          requestBody.destination = destAddress;
        } else {
          this.patchDistance(deliveryId, type, {
            distance: '',
            duration: '',
            loading: false,
            error: 'No destination available',
          });
          return;
        }

        const response = await ApiService.post(
          '/driver/deliveries/calculate-eta',
          requestBody
        );

        if (response.success !== false) {
          this.patchDistance(deliveryId, type, {
            distance: response.distance || '',
            duration: response.duration || '',
            loading: false,
          });
        } else {
          this.patchDistance(deliveryId, type, {
            distance: '',
            duration: '',
            loading: false,
            error: response.error || 'Unable to calculate',
          });
        }
      } catch (error) {
        console.error(`Error calculating ${type} distance:`, error);
        this.patchDistance(deliveryId, type, {
          distance: '',
          duration: '',
          loading: false,
          error: 'Calculation failed',
        });
      }
    },
    patchDistance(deliveryId, type, patch) {
      const prev = this.distances[deliveryId] || {
        pickup: {},
        dropoff: {},
      };
      this.$set(this.distances, deliveryId, {
        ...prev,
        [type]: { ...prev[type], ...patch },
      });
    },
    etaLine(dt) {
      if (!dt) return '—';
      if (dt.distance && dt.duration) {
        return `${dt.distance} • ${dt.duration}`;
      }
      return '—';
    },
    onRefresh() {
      this.refreshing = true;
      this.fetchPendingOrders();
    },
    prev() {
      if (this.canGoPrev) {
        this.currentIndex -= 1;
      }
    },
    next() {
      if (this.canGoNext) {
        this.currentIndex += 1;
      }
    },
    handleAccept(deliveryId) {
      if (
        !window.confirm('Are you sure you want to accept this order?')
      ) {
        return;
      }
      ApiService.post(`/driver/deliveries/${deliveryId}/accept`, {})
        .then((response) => {
          if (response.success !== false) {
            window.alert(
              'Delivery accepted! Status changed to picking up.'
            );
            this.$router.push({ name: 'OngoingOrders' });
          } else {
            window.alert(response.message || 'Failed to accept delivery');
          }
        })
        .catch((error) => {
          console.error('Error accepting delivery:', error);
          window.alert(error.message || 'Failed to accept delivery');
        });
    },
    handleDecline(deliveryId) {
      if (!window.confirm('Are you sure you want to reject this order?')) {
        return;
      }
      ApiService.post(`/driver/deliveries/${deliveryId}/decline`, {})
        .then((response) => {
          if (response.success !== false) {
            window.alert('Order rejected.');
            this.fetchPendingOrders();
          } else {
            window.alert(response.message || 'Failed to decline delivery');
          }
        })
        .catch((error) => {
          console.error('Error declining delivery:', error);
          window.alert(error.message || 'Failed to decline delivery');
        });
    },
  },
};
</script>

